"""Implementation of actions for the DCM Tree application"""

from interops.libraries.squish_actions import CommonActions
from interops.libraries.squish_actions.constants import DCMTREE_APP_NAME
from interops.libraries.desktop import AutManager
from interops.libraries.desktop import decorators as deco
from .objects.dcmtree_objects import DCMTree
from typing import Tuple
import os

def set_dcmtree_application_as_context() -> None:
    """Sets the Squish context to the DCM Tree application if it isn't already
    """
    if str(AutManager.get_current_app_context) != "DCMtree":
        AutManager.set_app_context("DCMtree")

@deco.set_separate_app_context(DCMTREE_APP_NAME)
def set_dcmtree_application_to_foreground() -> None:
    """Sets the DCM Tree main window to the foreground
    """
    CommonActions.set_context_application_to_foreground(DCMTree.dCMtree_Main_Window)

@deco.set_separate_app_context(DCMTREE_APP_NAME)
def add_dicom_file_to_tree(filePath: str) -> None:
    """Clicks the File > Add menu option from the top bar > then adds a given file via its file path

    :param str filePath: File path of the file to be added to the DCM Tree import
    """
    CommonActions.left_click_object(DCMTree.menuBar_Item_File)
    CommonActions.left_click_object(DCMTree.file_Add_MenuItem)
    CommonActions.os_choose_file(filePath)

@deco.set_separate_app_context(DCMTREE_APP_NAME)
def add_multiple_dicom_files_to_tree(folderPath: str) -> None:
    """Initiates the add_dicom_file_to_tree() function for each file inside of a given folder path.

    :param str folderPath: Folder path of the folder containing DICOM data to be added to the DCM Tree import
    """
    fileList = CommonActions.get_files_on_remote_system(folderPath)
    for file in fileList:
        add_dicom_file_to_tree(os.path.join(folderPath, file))

@deco.set_separate_app_context(DCMTREE_APP_NAME)
def open_transmit_dialog() -> None:
    """Clicks the File > Transmit menu option from the top bar > waits for the Transmit dialog to appear.
    """
    CommonActions.left_click_object(DCMTree.menuBar_Item_File)
    CommonActions.left_click_object(DCMTree.file_Transmit_MenuItem)
    CommonActions.find_object(DCMTree.transmit_DICOM_Dialog)

@deco.set_separate_app_context(DCMTREE_APP_NAME)
def type_ae_title_in_transmit_dialog(aeTitle: str) -> None:
    """Locates and types in a given AE Title into the AE Title combobox inside the Transmit Dialog.

    :param str aeTitle: AE Title string to be typed into the AE Title combox box
    """
    CommonActions.type_in_textfield(DCMTree.transmit_DICOM_AE_Title_ComboBox, aeTitle)

@deco.set_separate_app_context(DCMTREE_APP_NAME)
def type_host_name_in_transmit_dialog(hostName: str) -> None:
    """Locates and clears the Host Name text box inside the Transmit Dialog, before typing in a given Host Name string.

    :param str hostName: Host Name string to be typed into the Host Name text box
    """
    while (CommonActions.find_object(DCMTree.transmit_DICOM_Host_Name_Box).text != ""): #type: ignore
        CommonActions.double_click_object(DCMTree.transmit_DICOM_Host_Name_Box)
        CommonActions.press_delete_key()
    CommonActions.type_in_textfield(DCMTree.transmit_DICOM_Host_Name_Box, hostName)

@deco.set_separate_app_context(DCMTREE_APP_NAME)
def type_port_number_in_transmit_dialog(portNumber: str) -> None:
    """Locates and clears the Port Number text box inside the Transmit Dialog, before typing in a given Port Number string.
    (This also handles the pop up dialog when the text box is cleared.)

    :param str portNumber: Port Number string to be typed into the Port Number text box
    """
    if (CommonActions.find_object(DCMTree.transmit_DICOM_Port_Number_Box).text != ""): #type: ignore
        CommonActions.double_click_object(DCMTree.transmit_DICOM_Port_Number_Box)
        CommonActions.press_delete_key()
        CommonActions.press_enter_key()
    CommonActions.type_in_textfield(DCMTree.transmit_DICOM_Port_Number_Box, portNumber)

@deco.set_separate_app_context(DCMTREE_APP_NAME)
def click_send_button() -> None:
    """Locates and clicks the Send button in the Transmit Dialog.
    """
    CommonActions.left_click_object(DCMTree.transmit_DICOM_Send_button)

@deco.set_separate_app_context(DCMTREE_APP_NAME)
def wait_for_completed_transmission(timeoutInSecs: int = 1200) -> None:
    """Waits for the Transmit Dialogs "Send Progress" to disappear > then clears the Transmit Dialog.

    :param int timeoutInSecs: Timeout in seconds to wait for the DCMTree to finish sending (default is 10 minutes)
    """
    CommonActions.wait_for_object_to_disappear(DCMTree.sendProgress_Window, timeoutInSecs)
    CommonActions.press_esc_key()

@deco.set_separate_app_context(DCMTREE_APP_NAME)
def get_add_files_box_location() -> Tuple[int, int]:
    """Locates the DCM Tree File List Box and returns the XY coordinates

    :return: X & Y coordinates
    :rtype: Tuple[int, int]
    """
    fileListBox = CommonActions.find_object(DCMTree.dCMtree_File_List_Box)
    return fileListBox.x, fileListBox.y #type: ignore